/**
 * Guard Input Validate — keep today's fail-closed input checks.
 *
 * tenant_id REQUIRED -> GUARD_ERROR (UNKNOWN_CHANNEL_IDENTITY); module_key REQUIRED.
 * An input error item carries _cacheUsable:false (so Decide-from-cache never treats
 * it as a hit) AND _cacheable:false (so the Redis SET on the miss path is skipped) —
 * it flows through the cache-aside nodes and terminates as a deny WITHOUT a spurious
 * cache read or write.
 */
const input = $input.first().json;
const moduleKey = input.module_key;
const tenantId = (input.tenant_id || '').toString().trim();

if (!tenantId) {
  return [{ json: {
    allowed: false,
    reason: 'GUARD_ERROR: tenant_id not provided (UNKNOWN_CHANNEL_IDENTITY)',
    config_overrides: {},
    _inputError: true,
    _cacheUsable: false,
    _cacheable: false,
    tenant_id: '',
    module_key: moduleKey || ''
  } }];
}

if (!moduleKey) {
  return [{ json: {
    allowed: false,
    reason: 'GUARD_ERROR: module_key not provided',
    config_overrides: {},
    _inputError: true,
    _cacheUsable: false,
    _cacheable: false,
    tenant_id: tenantId,
    module_key: ''
  } }];
}

// Valid input — pass tenant_id/module_key through to the Redis key expression.
return [{ json: { tenant_id: tenantId, module_key: moduleKey } }];

/**
 * Decide-from-cache — inlined copy of entitlement-decision.mjs decideFromCache().
 * (n8n Code nodes cannot import the repo .mjs; the seam is the spec + test source
 * of truth, this is the byte-equivalent inline.)
 *
 * An input-error item (from Guard Input Validate) already carries _cacheUsable:false
 * and _cacheable:false — pass it straight through as a terminal deny (the IF below
 * routes _cacheUsable:false to the MISS branch, but _cacheable:false makes the
 * Evaluate node skip it and the SET is never reached).
 */
const item = $input.first().json;
const tenant_id = item.tenant_id;
const module_key = item.module_key;

// Input error -> terminal deny; never read/written.
if (item._inputError === true) {
  return [{ json: { ...item, _cacheUsable: false } }];
}

// The Redis GET node surfaces the value as $json (bare string), or {error} on
// continueOnFail. Normalize the candidate raw value.
let cachedRaw = null;
if (item && typeof item === 'object') {
  if ('error' in item && item.error) {
    cachedRaw = { error: item.error }; // Redis error envelope -> miss
  } else if (typeof item.value === 'string') {
    cachedRaw = item.value;
  } else if (typeof item.data === 'string') {
    cachedRaw = item.data;
  } else if (typeof item.result === 'string') {
    cachedRaw = item.result;
  }
}

function isGlobalModule(mod) {
  return !!mod && (mod.tier === 'shared_core' || mod.enabled_globally === true);
}
function isExpired(ent, now) {
  if (!ent || ent.expires_at === undefined || ent.expires_at === null || ent.expires_at === '') return false;
  const exp = new Date(ent.expires_at).getTime();
  if (Number.isNaN(exp)) return false;
  return exp < now;
}

const now = Date.now();
let decision = { cacheUsable: false };

if (cachedRaw !== null && cachedRaw !== undefined) {
  let obj = cachedRaw;
  if (typeof cachedRaw === 'string') {
    const s = cachedRaw.trim();
    if (s === '' || s.toLowerCase() === 'nil' || s.toLowerCase() === 'null') {
      obj = null;
    } else {
      try { obj = JSON.parse(s); } catch (e) { obj = null; }
    }
  }
  if (obj && typeof obj === 'object' && !('error' in obj)) {
    if (obj.neg === true) {
      decision = { cacheUsable: true, allowed: false, reason: 'NO_ENTITLEMENT', config_overrides: {} };
    } else if (obj.ent && typeof obj.ent === 'object') {
      const ent = obj.ent; const mod = obj.mod || {};
      if (isExpired(ent, now)) {
        decision = { cacheUsable: true, allowed: false, reason: 'EXPIRED', config_overrides: {} };
      } else {
        const reason = isGlobalModule(mod) ? 'GLOBAL_ENABLED_CACHED' : 'ENTITLED_CACHED';
        decision = { cacheUsable: true, allowed: true, reason, config_overrides: ent.config_overrides || {} };
      }
    } else if (obj.mod && isGlobalModule(obj.mod)) {
      decision = { cacheUsable: true, allowed: true, reason: 'GLOBAL_ENABLED_CACHED', config_overrides: {} };
    }
  }
}

return [{ json: {
  _cacheUsable: decision.cacheUsable,
  allowed: decision.allowed,
  reason: decision.reason,
  config_overrides: decision.config_overrides || {},
  tenant_id,
  module_key
} }];

// HIT — return the cached decision. ★ NO httpRequest node downstream of here.
return [{ json: {
  allowed: $json.allowed,
  reason: $json.reason,
  config_overrides: $json.config_overrides || {},
  tenant_id: $json.tenant_id,
  module_key: $json.module_key
} }];

/**
 * Evaluate live (fail-closed) — inlined copy of entitlement-decision.mjs evaluateLive().
 * Reads TTLs from env: ENTITLEMENT_CACHE_TTL_SEC (positive, default 300) /
 * ENTITLEMENT_NEG_CACHE_TTL_SEC (negative, default 60).
 *
 * Strapi-error detection FIRST (Pitfall 8): {error} / non-2xx / invalid body ->
 * GUARD_ERROR_FAILCLOSED, _cacheable:false (transient never cached). Else the live
 * ladder. An input-error item (carried from Guard Input Validate) is passed straight
 * through as a terminal deny with _cacheable:false so the SET is skipped.
 */
const posTtl = Number($env.ENTITLEMENT_CACHE_TTL_SEC) || 300;
const negTtl = Number($env.ENTITLEMENT_NEG_CACHE_TTL_SEC) || 60;
const now = Date.now();

const self = $input.first().json;
const tenant_id = self.tenant_id;
const module_key = self.module_key;

// Input error -> terminal deny, never cached.
if (self._inputError === true) {
  return [{ json: {
    allowed: false,
    reason: self.reason,
    config_overrides: {},
    _cacheRow: null,
    _cacheable: false,
    _cacheTtl: 0,
    tenant_id,
    module_key
  } }];
}

const moduleRes = $('Strapi - GET product-modules').item.json;
let entRes = null;
try { entRes = $('Strapi - GET tenant-entitlements').item.json; } catch (e) { entRes = null; }

function isGlobalModule(mod) {
  return !!mod && (mod.tier === 'shared_core' || mod.enabled_globally === true);
}
function isExpired(ent) {
  if (!ent || ent.expires_at === undefined || ent.expires_at === null || ent.expires_at === '') return false;
  const exp = new Date(ent.expires_at).getTime();
  if (Number.isNaN(exp)) return false;
  return exp < now;
}
function strapiError(res) {
  if (res === null || res === undefined) return 'empty response';
  if (typeof res !== 'object') return 'non-object response';
  if ('error' in res && res.error) {
    const e = res.error;
    if (typeof e === 'string') return e;
    if (e && typeof e === 'object') return e.message || e.name || 'strapi error';
    return 'strapi error';
  }
  const status = (res.statusCode !== undefined ? res.statusCode : res.status);
  if (typeof status === 'number' && (status < 200 || status >= 300)) return `HTTP ${status}`;
  if (!('data' in res)) return 'invalid body (no data field)';
  if (!Array.isArray(res.data)) return 'invalid body (data not an array)';
  return '';
}

let out;
const modErr = strapiError(moduleRes);
if (modErr) {
  out = { allowed: false, reason: `GUARD_ERROR_FAILCLOSED: product-modules ${modErr}`, config_overrides: {}, _cacheRow: null, _cacheable: false, _cacheTtl: 0 };
} else {
  const mod = moduleRes.data[0];
  if (!mod) {
    out = { allowed: false, reason: 'MODULE_NOT_FOUND', config_overrides: {}, _cacheRow: { neg: true }, _cacheable: true, _cacheTtl: negTtl };
  } else if (isGlobalModule(mod)) {
    out = { allowed: true, reason: 'GLOBAL_ENABLED', config_overrides: {}, _cacheRow: { mod, fetchedAt: new Date(now).toISOString() }, _cacheable: true, _cacheTtl: posTtl };
  } else {
    const entErr = strapiError(entRes);
    if (entErr) {
      out = { allowed: false, reason: `GUARD_ERROR_FAILCLOSED: tenant-entitlements ${entErr}`, config_overrides: {}, _cacheRow: null, _cacheable: false, _cacheTtl: 0 };
    } else {
      const ent = entRes.data[0];
      if (!ent) {
        out = { allowed: false, reason: 'NO_ENTITLEMENT', config_overrides: {}, _cacheRow: { neg: true }, _cacheable: true, _cacheTtl: negTtl };
      } else if (isExpired(ent)) {
        out = { allowed: false, reason: 'EXPIRED', config_overrides: {}, _cacheRow: { neg: true }, _cacheable: true, _cacheTtl: negTtl };
      } else {
        out = { allowed: true, reason: 'ENTITLED', config_overrides: ent.config_overrides || {}, _cacheRow: { ent, mod, fetchedAt: new Date(now).toISOString() }, _cacheable: true, _cacheTtl: posTtl };
      }
    }
  }
}

return [{ json: { ...out, tenant_id, module_key } }];

// Return fresh decision — strip the _cache* internals. Both the SET (main[0])
// and the IF-Cacheable FALSE (main[1], error/input-error path skipping SET)
// branches converge here.
return [{ json: {
  allowed: $json.allowed,
  reason: $json.reason,
  config_overrides: $json.config_overrides || {},
  tenant_id: $json.tenant_id,
  module_key: $json.module_key
} }];
